const msg = $('TelegramTrigger').first().json.message;
const fileId = msg.voice?.file_id || msg.audio?.file_id;
if (!fileId) {
  return [{ json: { error: 'No audio file_id found' } }];
}

const BOT_TOKEN = 'BOT_TOKEN_REDACTED';

// Step 1: Get file path from Telegram
const fileData = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://api.telegram.org/bot' + BOT_TOKEN + '/getFile',
  qs: { file_id: fileId },
  json: true
});
if (!fileData.ok) {
  return [{ json: { error: 'Telegram getFile failed', details: fileData } }];
}
const filePath = fileData.result.file_path;

// Step 2: Download the audio binary
const audioBuffer = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://api.telegram.org/file/bot' + BOT_TOKEN + '/' + filePath,
  encoding: 'arraybuffer',
  returnFullResponse: false
});
const audioBase64 = Buffer.from(audioBuffer).toString('base64');

// Step 3: Send to OpenRouter (Gemini 2.5 Flash) for transcription
const OPENROUTER_KEY = 'sk-or-v1-REDACTED';
const sttData = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://openrouter.ai/api/v1/chat/completions',
  headers: {
    'Authorization': 'Bearer ' + OPENROUTER_KEY,
    'Content-Type': 'application/json'
  },
  body: {
    model: 'google/gemini-2.5-flash',
    messages: [{
      role: 'user',
      content: [
        { type: 'text', text: 'Por favor transcribe exactamente lo que se dice en este audio. Respeta la mezcla de espanol e ingles (Spanglish) y los terminos tecnicos. Solo devuelve la transcripcion directa, sin comentarios.' },
        { type: 'input_audio', input_audio: { data: audioBase64, format: 'ogg' } }
      ]
    }]
  },
  json: true
});

const transcription = sttData?.choices?.[0]?.message?.content || '';
return [{ json: { candidates: [{ content: { parts: [{ text: transcription }] } }] } }];

let text = "";
const trig = $('TelegramTrigger').first().json.message;

try {
  const geminiOut = $('Gemini Audio to Text').first()?.json;
  if (geminiOut && geminiOut.candidates && geminiOut.candidates[0].content.parts[0].text) {
    text = geminiOut.candidates[0].content.parts[0].text;
  }
} catch (e) {}

if (!text) {
  text = trig.text || "";
}

return {
  json: {
    user_input: text,
    chat_id: trig.chat.id,
    message_id: trig.message_id,
    is_bot: trig.from.is_bot || false
  }
};

const notionToken = "ntn_REDACTED";
const notionHeaders = {
  "Authorization": `Bearer ${notionToken}`,
  "Notion-Version": "2022-06-28",
  "Content-Type": "application/json"
};

const vikunjaToken = "tk_REDACTED";
const vikunjaHeaders = {
  "Authorization": `Bearer ${vikunjaToken}`,
  "Content-Type": "application/json"
};

const telegramToken = "BOT_TOKEN_REDACTED";

// 1. Extract inputs
const item = $input.first().json;
const userInput = item.user_input || "";
const chatId = item.chat_id;
const messageId = item.message_id;
const isBot = item.is_bot || false;

// Whitelist checks (allow positive user IDs and known groups)
const isAllowedChat = chatId > 0 || chatId === -1003531406167 || chatId === -5130651596;

if (isBot || !isAllowedChat || !userInput.trim()) {
  return { json: { status: "ignored", reason: "Bot message, unauthorized chat, or empty input" } };
}

// 2. Fetch context
let vikunjaProjects = [];
try {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: 'http://10.147.18.4:3456/api/v1/projects',
    headers: { "Authorization": `Bearer ${vikunjaToken}` },
    json: true
  });
  vikunjaProjects = resp.map(p => ({ id: p.id, name: p.title }));
} catch (e) {
  console.error("Error fetching Vikunja projects:", e);
}

let notionEpics = [];
try {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.notion.com/v1/databases/381c22d5-8177-8159-a848-e2ece2dde69b/query',
    headers: notionHeaders,
    json: true
  });
  notionEpics = resp.results.map(page => {
    const nameProp = page.properties.Name || {};
    const name = nameProp.title && nameProp.title[0] ? nameProp.title[0].plain_text : "Untitled";
    return { id: page.id, name };
  });
} catch (e) {
  console.error("Error fetching Notion Epics:", e);
}

let notionSprints = [];
let activeSprintId = null;
try {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.notion.com/v1/databases/381c22d5-8177-813a-9613-d1fa2d06b676/query',
    headers: notionHeaders,
    json: true
  });
  notionSprints = resp.results.map(page => {
    const nameProp = page.properties.Name || {};
    const name = nameProp.title && nameProp.title[0] ? nameProp.title[0].plain_text : "Untitled";
    const status = page.properties.Estado?.status?.name || "";
    if (status === "In progress") {
      activeSprintId = page.id;
    }
    return { id: page.id, name, status };
  });
} catch (e) {
  console.error("Error fetching Notion Sprints:", e);
}

const contextObj = {
  notion_epics: notionEpics,
  notion_sprints: notionSprints,
  vikunja_projects: vikunjaProjects,
  vikunja_users: [
    { id: 1, name: "Dario", role: "Gerencia General" },
    { id: 2, name: "Lourdes", role: "Administración / Gastos" },
    { id: 3, name: "Yumaira", role: "Administración Externa / Contable" },
    { id: 4, name: "Yasmibel", role: "Supervisión / Ventas / Caja" },
    { id: 5, name: "Ariany", role: "Ventas / Operaciones / Cadena de frío" }
  ]
};

// 3. Call Dify
let difyResult = null;
try {
  const difyResponse = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://dify.farmaciaamericana.es/v1/workflows/run',
    headers: {
      "Authorization": "Bearer app-REDACTED",
      "Content-Type": "application/json"
    },
    body: {
      inputs: {
        user_input: userInput,
        context_json: JSON.stringify(contextObj),
        // Adding backward compatibility fields so Dify doesn't throw 400
        titulo: userInput.substring(0, 50) + "...",
        descripcion: userInput,
        lista_proyectos: JSON.stringify(contextObj)
      },
      response_mode: 'blocking',
      user: 'n8n-system'
    },
    json: true
  });

  const text = difyResponse.data?.outputs?.text || difyResponse.data?.outputs?.result || '{}';
  difyResult = JSON.parse(text.trim());
} catch (e) {
  console.error("Error calling Dify:", e);
  let errorMsg = e.message;
  if (e.response && e.response.data) {
    errorMsg = JSON.stringify(e.response.data);
  }
  await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.telegram.org/bot${telegramToken}/sendMessage`,
    body: {
      chat_id: chatId,
      text: `❌ *Error técnico*: No se pudo clasificar la tarea con Dify.
_${errorMsg}_`,
      parse_mode: "Markdown",
      reply_to_message_id: messageId
    },
    json: true
  });
  throw e;
}

// Resilient parsing: if Dify gives the old format (only project_id), default to Vikunja
const target = difyResult.target || "Vikunja";
let projectId = difyResult.project_id;
const assigneeName = difyResult.assignee_id || "Dario";
const title = difyResult.title || userInput.substring(0, 40) + "...";
const description = difyResult.description_enhanced || userInput;
const createNewEntity = difyResult.create_new_entity || false;
const newEntityName = difyResult.new_entity_name || "";

let feedbackMessage = "";

if (target === "Notion") {
  if (createNewEntity && newEntityName) {
    try {
      const newEpic = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://api.notion.com/v1/pages',
        headers: notionHeaders,
        body: {
          parent: { database_id: "381c22d5-8177-8159-a848-e2ece2dde69b" },
          properties: {
            Name: { title: [{ text: { content: newEntityName } }] }
          }
        },
        json: true
      });
      projectId = newEpic.id;
      feedbackMessage += `🆕 *Épica Creada*: ${newEntityName}\n`;
    } catch (e) {
      console.error("Error creating Notion Epic:", e);
      feedbackMessage += `⚠️ *Fallo al crear Épica*: ${newEntityName} (usando Epic default)\n`;
    }
  }

  try {
    const properties = {
      Name: { title: [{ text: { content: title } }] }
    };
    if (projectId) {
      properties["Épica"] = { relation: [{ id: projectId }] };
    }
    if (activeSprintId) {
      properties["Sprint"] = { relation: [{ id: activeSprintId }] };
    }
    properties["Estado"] = { status: { name: "Not started" } };

    const notionPage = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.notion.com/v1/pages',
      headers: notionHeaders,
      body: {
        parent: { database_id: "381c22d5-8177-81fb-89ee-e34715f74d63" },
        properties: properties,
        children: [
          {
            object: 'block',
            type: 'paragraph',
            paragraph: {
              rich_text: [{ type: 'text', text: { content: description } }]
            }
          }
        ]
      },
      json: true
    });

    feedbackMessage += `✅ *Tarea Creada en Notion (Software Dev)*\n`;
    feedbackMessage += `📌 *Título*: ${title}\n`;
    if (projectId) {
      const epicName = notionEpics.find(e => e.id === projectId)?.name || newEntityName || "Asociada";
      feedbackMessage += `📁 *Épica*: ${epicName}\n`;
    }
    feedbackMessage += `👤 *Asignado*: ${assigneeName}\n`;
  } catch (e) {
    console.error("Error creating Notion task:", e);
    throw new Error("Failed to create Notion task: " + e.message);
  }

} else if (target === "Vikunja") {
  if (createNewEntity && newEntityName) {
    try {
      const newProj = await this.helpers.httpRequest({
        method: 'PUT',
        url: 'http://10.147.18.4:3456/api/v1/projects',
        headers: {
          "Authorization": `Bearer ${vikunjaToken}`,
          "Content-Type": "application/json"
        },
        body: { title: newEntityName },
        json: true
      });
      projectId = newProj.id;
      feedbackMessage += `🆕 *Proyecto Creado*: ${newEntityName}\n`;
    } catch (e) {
      console.error("Error creating Vikunja project:", e);
      feedbackMessage += `⚠️ *Fallo al crear Proyecto*: ${newEntityName} (usando default)\n`;
    }
  }

  const finalProjectId = projectId || 3;

  let assigneeId = null;
  let enhancedDescription = description;
  if (assigneeName.toLowerCase().includes("dario")) {
    assigneeId = 1;
  } else {
    enhancedDescription = `[Asignado a: ${assigneeName}]\n\n${description}`;
  }

  try {
    const task = await this.helpers.httpRequest({
      method: 'PUT',
      url: `http://10.147.18.4:3456/api/v1/projects/${finalProjectId}/tasks`,
      headers: {
        "Authorization": `Bearer ${vikunjaToken}`,
        "Content-Type": "application/json"
      },
      body: {
        title: title,
        description: enhancedDescription
      },
      json: true
    });

    const taskId = task.id;

    if (assigneeId) {
      try {
        await this.helpers.httpRequest({
          method: 'PUT',
          url: `http://10.147.18.4:3456/api/v1/tasks/${taskId}/assignees`,
          headers: {
            "Authorization": `Bearer ${vikunjaToken}`,
            "Content-Type": "application/json"
          },
          body: { user_id: assigneeId },
          json: true
        });
      } catch (ae) {
        console.error("Error assigning task:", ae);
      }
    }

    feedbackMessage += `✅ *Tarea Creada en Vikunja (Operaciones)*\n`;
    feedbackMessage += `📌 *Título*: ${title}\n`;
    const projName = vikunjaProjects.find(p => p.id === finalProjectId)?.name || newEntityName || "Operaciones";
    feedbackMessage += `📁 *Proyecto*: ${projName}\n`;
    feedbackMessage += `👤 *Asignado*: ${assigneeName}\n`;

  } catch (e) {
    console.error("Error creating Vikunja task:", e);
    throw new Error("Failed to create Vikunja task: " + e.message);
  }
} else {
  feedbackMessage = `⚠️ *Clasificación Desconocida*: El target '${target}' no es válido.`;
}

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.telegram.org/bot${telegramToken}/sendMessage`,
    body: {
      chat_id: chatId,
      text: feedbackMessage,
      parse_mode: "Markdown",
      reply_to_message_id: messageId
    },
    json: true
  });
} catch (te) {
  console.error("Error sending Telegram feedback:", te);
}

return {
  json: {
    status: "success",
    target: target,
    title: title,
    project_id: projectId
  }
};
